def compute(vars):
    old_cost = vars["v1"]
    new_cost = vars["v2"]
    change = new_cost - old_cost

    return {
        "value": change,
        "trace": {
            "old_cost": old_cost,
            "new_cost": new_cost,
            "change": change,
            "output_meta": {
                "currency": "CNY",
                "scale": "million",
                "unit": None
            }
        }
    }
